/* Fundo rotativo: troca de imagem a cada 10 s (9 fotos 4K selecionadas). Arquivo único: imagens e estilo incluídos. */
(function(){
  var INTERVALO=10000; /* tempo de cada imagem, em ms */
  var IMAGENS=["data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,"];
  var st=document.createElement('style');st.textContent=".bg{position:fixed;top:0;right:0;bottom:0;left:0;z-index:0;pointer-events:none;background:#000 center/cover no-repeat;opacity:0;transition:opacity 1.2s ease;--scrim:.5}\n.bg.on{opacity:1}\n.bg::after{content:\"\";position:absolute;top:0;right:0;bottom:0;left:0;background:linear-gradient(180deg,rgba(0,0,0,calc(var(--scrim) + .1)) 0%,rgba(0,0,0,var(--scrim)) 45%,rgba(0,0,0,calc(var(--scrim) + .12)) 100%)}\n:root{--card:rgba(8,8,8,.84)}\n.wrap{position:relative;z-index:1}\n.card{border-color:rgba(255,255,255,.14)}\n.tabs button:not(.on){background:rgba(8,8,8,.84)}\nheader h1,header p,.today{text-shadow:0 2px 12px rgba(0,0,0,.7)}";document.head.appendChild(st);
  var atual=-1,ultimo=document.getElementById('bg'),FADE=1300;
  function indiceInicial(){var d=new Date();return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/864e5)%IMAGENS.length}
  function pelicula(img,el){
    var s=.5;
    try{var c=document.createElement('canvas');c.width=c.height=24;var x=c.getContext('2d');x.drawImage(img,0,0,24,24);
      var p=x.getImageData(0,0,24,24).data,t=0;for(var i=0;i<p.length;i+=4)t+=(p[i]*.299+p[i+1]*.587+p[i+2]*.114)/255;
      s=Math.min(.74,Math.max(.42,.36+t/(p.length/4)*.5))}catch(e){}
    el.style.setProperty('--scrim',s.toFixed(2));
  }
  /* Mostra a imagem i por cima da anterior (crossfade) e remove a camada antiga depois da transição */
  function mostrar(i){
    var img=new Image();
    img.onload=function(){
      if(i!==atual)return;
      var el=document.createElement('div');el.className='bg';el.setAttribute('aria-hidden','true');
      pelicula(img,el);
      el.style.backgroundImage='url("'+IMAGENS[i]+'")';
      if(ultimo&&ultimo.parentNode)ultimo.parentNode.insertBefore(el,ultimo.nextSibling);
      else document.body.insertBefore(el,document.body.firstChild);
      var velho=ultimo;ultimo=el;
      requestAnimationFrame(function(){requestAnimationFrame(function(){el.classList.add('on')})});
      if(velho)setTimeout(function(){if(velho.parentNode)velho.parentNode.removeChild(velho)},FADE+200);
    };
    img.src=IMAGENS[i];
  }
  function avancar(){
    if(document.hidden)return; /* aba em segundo plano: não troca */
    atual=(atual+1)%IMAGENS.length;mostrar(atual);
  }
  atual=indiceInicial()-1;avancar();setInterval(avancar,INTERVALO);
})();
